import { sleep, toErrorMessage } from "../utils.js";
import type { BrightApiContext } from "../types.js";
import type { AppHealthMonitor } from "../app-health.js";

const DEFAULT_ATTACK_LOCATIONS = ["body", "query", "fragment"];
const PATH_ATTACK_LOCATIONS = ["body", "query", "fragment", "path"];

export async function runSecurityScan(
  projectId: string,
  entrypointIds: string[],
  repeaterId: string,
  testTags: string[],
  api: BrightApiContext,
  scanName?: string,
  hasPathParams = false,
): Promise<string> {
  const locations = hasPathParams
    ? PATH_ATTACK_LOCATIONS
    : DEFAULT_ATTACK_LOCATIONS;
  console.log(
    `[Scan] Starting scan with ${entrypointIds.length} entrypoints, ${testTags.length} tests [${testTags.join(", ")}], attack locations: ${locations.join(", ")}`,
  );

  return runScanViaRest(
    api,
    projectId,
    entrypointIds,
    repeaterId,
    testTags,
    locations,
    scanName,
  );
}

async function runScanViaRest(
  api: BrightApiContext,
  projectId: string,
  entrypointIds: string[],
  repeaterId: string,
  testTags: string[],
  attackParamLocations: string[],
  scanName?: string,
): Promise<string> {
  let tests = [...testTags];
  let eps = [...entrypointIds];
  let locations = [...attackParamLocations];
  const maxRetries = 4;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const body = {
      name: scanName ?? `Engine Scan ${new Date().toISOString()}`,
      projectId,
      module: "dast",
      discoveryTypes: null,
      entryPointIds: eps,
      repeaters: [repeaterId],
      tests,
      attackParamLocations: locations,
      smart: true,
      skipStaticParams: true,
      poolSize: 10,
      requestsRateLimit: 0,
      singleTabScanActive: false,
      exclusions: { requests: [] },
    };

    let res: Response;
    try {
      res = await fetch(`https://${api.brightHostname}/api/v1/scans`, {
        method: "POST",
        headers: {
          Authorization: `Api-Key ${api.brightToken}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      });
    } catch (err) {
      // TCP/network error — retry
      const msg = toErrorMessage(err);
      console.warn(
        `[Scan] Network error on attempt ${attempt}/${maxRetries}: ${msg}`,
      );
      if (attempt < maxRetries) {
        await sleep(5_000 * attempt);
        continue;
      }
      throw new Error(`runScan failed after ${maxRetries} attempts: ${msg}`);
    }

    if (res.ok) {
      const data = (await res.json()) as Record<string, unknown>;
      const scanId = (data.id ?? data.scanId) as string | undefined;
      if (!scanId) {
        throw new Error(
          `runScan REST returned no scanId: ${JSON.stringify(data).slice(0, 500)}`,
        );
      }
      console.log(`[Scan] Scan started (REST): ${scanId}`);
      return scanId;
    }

    const text = await res.text();

    // Rate limit — back off and retry
    if (res.status === 429) {
      console.warn(
        `[Scan] Rate limited (attempt ${attempt}/${maxRetries}), backing off...`,
      );
      if (attempt < maxRetries) {
        await sleep(10_000 * attempt);
        continue;
      }
      throw new Error(`runScan rate limited after ${maxRetries} attempts`);
    }

    // Server error — retry
    if (res.status >= 500) {
      console.warn(
        `[Scan] Server error ${res.status} (attempt ${attempt}/${maxRetries}): ${text.slice(0, 200)}`,
      );
      if (attempt < maxRetries) {
        await sleep(5_000 * attempt);
        continue;
      }
      throw new Error(
        `runScan REST failed (${res.status}): ${text.slice(0, 500)}`,
      );
    }

    // 400 validation error — try to auto-fix
    if (res.status === 400) {
      const errorDetails = parseValidationError(text);
      console.warn(
        `[Scan] 400 error (attempt ${attempt}/${maxRetries}): ${errorDetails.summary}`,
      );

      if (attempt >= maxRetries) break;

      // Strategy 1: fix test config issues (mutually exclusive, auth conflicts)
      const fixedTests = tryFixScanConfig(text, tests);
      if (fixedTests) {
        tests = fixedTests;
        console.log(
          `[Scan] Retrying with ${tests.length} tests after removing incompatible ones`,
        );
        continue;
      }

      // Strategy 2: remove invalid entrypoint IDs mentioned in error
      if (errorDetails.invalidEntrypoints.length > 0) {
        const invalidSet = new Set(errorDetails.invalidEntrypoints);
        const filtered = eps.filter((id) => !invalidSet.has(id));
        if (filtered.length > 0 && filtered.length < eps.length) {
          console.log(
            `[Scan] Removed ${eps.length - filtered.length} invalid entrypoint(s), retrying with ${filtered.length}`,
          );
          eps = filtered;
          continue;
        }
      }

      // Strategy 3: if error mentions specific field issues, try without optional params
      if (errorDetails.fieldErrors.length > 0) {
        const hasLocationErr = errorDetails.fieldErrors.some(
          (f) => f.includes("attackParam") || f.includes("location"),
        );
        if (hasLocationErr && locations.length > DEFAULT_ATTACK_LOCATIONS.length) {
          console.log(`[Scan] Removing path from attack locations and retrying`);
          locations = [...DEFAULT_ATTACK_LOCATIONS];
          continue;
        }
      }

      // Strategy 4: reduce entrypoints (binary search for bad batch)
      if (eps.length > 5) {
        const prev = eps.length;
        eps = eps.slice(0, Math.ceil(prev / 2));
        console.log(
          `[Scan] Retrying with ${eps.length} entrypoints (reduced from ${prev})`,
        );
        continue;
      }

      // Strategy 5: last resort — try with just 1 entrypoint to isolate config vs data issue
      if (eps.length > 1) {
        console.log(`[Scan] Isolating: trying single entrypoint to check if config is the issue`);
        eps = [eps[0]];
        continue;
      }
    }

    throw new Error(
      `runScan REST failed (${res.status}): ${text.slice(0, 800)}`,
    );
  }

  throw new Error(
    `runScan: exhausted retries. Last config: ${eps.length} eps, tests=[${tests.join(",")}]`,
  );
}

export interface ValidationErrorInfo {
  summary: string;
  invalidEntrypoints: string[];
  fieldErrors: string[];
}

/**
 * Parse a 400 validation error response from the Bright API.
 * Extracts field-level errors and invalid entrypoint IDs when available.
 */
export function parseValidationError(text: string): ValidationErrorInfo {
  const invalidEntrypoints: string[] = [];
  const fieldErrors: string[] = [];
  let summary = text.slice(0, 600);

  try {
    const parsed = JSON.parse(text);
    // NestJS class-validator format: { message: [...], error: "Bad Request" }
    // or { message: "...", errors: [{...}] }
    const messages: string[] = [];

    if (Array.isArray(parsed.message)) {
      messages.push(...parsed.message.map(String));
    } else if (typeof parsed.message === "string") {
      messages.push(parsed.message);
    }
    if (Array.isArray(parsed.errors)) {
      for (const err of parsed.errors) {
        const msg = err.message ?? err.constraints
          ? Object.values(err.constraints ?? {}).join("; ")
          : JSON.stringify(err);
        messages.push(String(msg));
      }
    }

    // Extract field-level validation hints
    for (const msg of messages) {
      if (msg.includes("entryPointIds") || msg.includes("entry_point")) {
        fieldErrors.push(msg);
        // Try to pull out specific IDs
        const idMatches = msg.match(/[a-zA-Z0-9]{20,}/g);
        if (idMatches) invalidEntrypoints.push(...idMatches);
      } else if (msg !== "One or more validation errors occurred.") {
        fieldErrors.push(msg);
      }
    }

    summary = messages.join(" | ").slice(0, 600) || summary;
  } catch {
    // Not JSON — use raw text
    // Try to find entrypoint IDs in raw text
    const idMatches = text.match(/entryPointIds[^[]*\[([^\]]+)\]/);
    if (idMatches) {
      const ids = idMatches[1].match(/[a-zA-Z0-9]{20,}/g);
      if (ids) invalidEntrypoints.push(...ids);
    }
  }

  return { summary, invalidEntrypoints, fieldErrors };
}

/**
 * Try to fix scan config by parsing the error and removing offending tests.
 * Returns the fixed test list, or null if the error isn't fixable.
 */
export function tryFixScanConfig(errorText: string, tests: string[]): string[] | null {
  const lower = errorText.toLowerCase();

  // "X test is mutually exclusive with other tests"
  if (lower.includes("mutually exclusive")) {
    // Try to identify which test from the error message
    const exclusiveTests = ["lrrl"];
    const toRemove = new Set(
      exclusiveTests.filter((ex) => lower.includes(ex) || tests.includes(ex)),
    );
    if (toRemove.size > 0) {
      const filtered = tests.filter((t) => !toRemove.has(t));
      if (filtered.length < tests.length && filtered.length > 0) {
        console.log(
          `[Scan] Removed mutually exclusive test(s), ${tests.length} → ${filtered.length}`,
        );
        return filtered;
      }
    }
  }

  // "multiple auth attack tests" — remove broken_access_control
  if (
    lower.includes("multiple auth attack tests") ||
    lower.includes("custom auth objects")
  ) {
    const filtered = tests.filter((t) => t !== "broken_access_control");
    if (filtered.length < tests.length && filtered.length > 0) {
      console.log(
        `[Scan] Removed multi-auth test(s), ${tests.length} → ${filtered.length}`,
      );
      return filtered;
    }
  }

  return null;
}

const TERMINAL_STATUSES = new Set([
  "done",
  "completed",
  "stopped",
  "failed",
  "disrupted",
]);

function isTerminalStatus(status: string): boolean {
  return TERMINAL_STATUSES.has(status.toLowerCase());
}

function isFailureStatus(status: string): boolean {
  const s = status.toLowerCase();
  return s === "failed" || s === "disrupted" || s === "timeout";
}

export { isFailureStatus };

function isPausedStatus(status: string): boolean {
  return status.toLowerCase() === "paused";
}

export async function waitForScanCompletion(
  api: BrightApiContext,
  scanId: string,
  onProgress?: (status: string, issuesFound: number) => void,
  healthMonitor?: AppHealthMonitor,
): Promise<string> {
  const pollInterval = 30_000;
  let pausedByMonitor = false;
  // Track how long the app has been continuously unhealthy. If the quick
  // compose restart (the only recovery the health monitor does) didn't fix
  // it, bail out so the orchestrator's serial flow can do a full restart.
  let unhealthySince: number | undefined;
  const UNHEALTHY_BAIL_MS = 120_000; // 2 minutes

  // Initial wait before first poll
  await sleep(pollInterval);

  while (true) {
    // Reactive lifecycle control: pause the scan in Bright while the target
    // is unhealthy, resume it once recovery succeeds. Avoids burning scan
    // budget on requests that are doomed to fail with "target is down".
    if (healthMonitor) {
      const healthy = healthMonitor.isHealthy();
      if (!healthy && !pausedByMonitor) {
        const ok = await setScanLifecycle(api, scanId, "pause");
        if (ok) {
          pausedByMonitor = true;
          console.log(
            `[Scan] Paused ${scanId} — app unhealthy, will resume after recovery`,
          );
        }
        if (!unhealthySince) unhealthySince = Date.now();
      } else if (!healthy && unhealthySince) {
        // Still unhealthy — check if we've waited too long
        const elapsed = Date.now() - unhealthySince;
        if (elapsed >= UNHEALTHY_BAIL_MS) {
          console.warn(
            `[Scan] App unhealthy for ${Math.round(elapsed / 1000)}s — bailing out of scan wait for orchestrator to handle`,
          );
          // Stop the scan so it doesn't keep running against a dead app
          await setScanLifecycle(api, scanId, "stop");
          return "disrupted";
        }
      } else if (healthy && pausedByMonitor) {
        const ok = await setScanLifecycle(api, scanId, "resume");
        if (ok) {
          pausedByMonitor = false;
          console.log(`[Scan] Resumed ${scanId} — app healthy again`);
        }
        unhealthySince = undefined;
      } else if (healthy) {
        unhealthySince = undefined;
      }
    }

    const scanStatus = await getScanStatusWithRetry(
      api,
      scanId,
    );
    const issues = scanStatus.issuesFound;

    onProgress?.(scanStatus.status, issues);

    // Bright can report a scan as paused even if this process did not pause it
    // (for example, a server-side pause or a previous lifecycle call whose local
    // state was lost). If the target is healthy, resume it proactively instead
    // of polling a paused scan forever.
    if (isPausedStatus(scanStatus.status)) {
      const healthy = healthMonitor?.isHealthy() ?? true;
      if (healthy) {
        const ok = await setScanLifecycle(api, scanId, "resume");
        if (ok) {
          pausedByMonitor = false;
          unhealthySince = undefined;
          console.log(
            `[Scan] Resumed ${scanId} — Bright reported paused while app is healthy`,
          );
        }
      }
    }

    if (isTerminalStatus(scanStatus.status)) {
      console.log(`[Scan] Completed: ${scanStatus.status} (${issues} issues)`);
      return scanStatus.status.toLowerCase();
    }

    // Per-poll progress is logged by the caller's onProgress callback
    // (orchestrator: "[Scan] Scan i/N: status — N issue(s)"). Avoid emitting
    // a second redundant line per poll.
    await sleep(pollInterval);
  }
}

/**
 * Drive a scan's lifecycle (pause/resume/stop/run) via Bright's REST API.
 * Returns true on 2xx, false on any failure (logged but not thrown — callers
 * treat lifecycle control as best-effort).
 */
export async function setScanLifecycle(
  api: BrightApiContext,
  scanId: string,
  action: "pause" | "resume" | "stop" | "run",
): Promise<boolean> {
  const url = `https://${api.brightHostname}/api/v1/scans/${encodeURIComponent(scanId)}/lifecycle`;
  try {
    const res = await fetch(url, {
      method: "PUT",
      headers: {
        Authorization: `Api-Key ${api.brightToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ action }),
    });
    if (!res.ok) {
      const body = await res.text().catch(() => "");
      console.warn(
        `[Scan] Lifecycle ${action} for ${scanId} failed (${res.status}): ${body.slice(0, 200)}`,
      );
      return false;
    }
    return true;
  } catch (err) {
    console.warn(
      `[Scan] Lifecycle ${action} for ${scanId} threw: ${toErrorMessage(err)}`,
    );
    return false;
  }
}

async function getScanStatusWithRetry(
  api: BrightApiContext,
  scanId: string,
): Promise<{ status: string; issuesFound: number }> {
  const maxAttempts = 3;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await getScanStatusViaRest(api, scanId);
    } catch (err) {
      if (attempt === maxAttempts) throw err;
      console.warn(
        `[Scan] getScanStatus retry ${attempt}/${maxAttempts} for ${scanId}: ${toErrorMessage(err)}`,
      );
      await sleep(5_000 * attempt);
    }
  }
  throw new Error("unreachable");
}

async function getScanStatusViaRest(
  api: BrightApiContext,
  scanId: string,
): Promise<{ status: string; issuesFound: number }> {
  const url = `https://${api.brightHostname}/api/v1/scans/${encodeURIComponent(scanId)}`;
  const res = await fetch(url, {
    headers: { Authorization: `Api-Key ${api.brightToken}` },
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(
      `getScanStatus failed (${res.status}): ${text.slice(0, 300)}`,
    );
  }

  const data = (await res.json()) as Record<string, unknown>;

  const issuesFound = extractIssueCount(data);

  return {
    status: (data.status as string) ?? "unknown",
    issuesFound,
  };
}

/**
 * Extract total issue count from a scan REST response (ScanView schema).
 *
 * Primary: uses the per-severity top-level fields (current API):
 *   numberOfCriticalSeverityIssues, numberOfHighSeverityIssues,
 *   numberOfMediumSeverityIssues, numberOfLowSeverityIssues
 *
 * Secondary: issuesLength (total count field on ScanView).
 *
 * Tertiary: deprecated issuesBySeverity array where each item is
 *   { type: "Medium", number: 4, issuesByStatus: [...] }
 */
function extractIssueCount(data: Record<string, unknown>): number {
  const severityFields = [
    "numberOfCriticalSeverityIssues",
    "numberOfHighSeverityIssues",
    "numberOfMediumSeverityIssues",
    "numberOfLowSeverityIssues",
  ] as const;

  let total = 0;
  let hasSeverityFields = false;
  for (const field of severityFields) {
    if (typeof data[field] === "number") {
      total += data[field] as number;
      hasSeverityFields = true;
    }
  }
  if (hasSeverityFields) return total;

  if (typeof data.issuesLength === "number") return data.issuesLength;

  // Deprecated: issuesBySeverity is an array of { type, number, issuesByStatus }
  if (Array.isArray(data.issuesBySeverity)) {
    for (const item of data.issuesBySeverity) {
      if (
        typeof item === "object" &&
        item !== null &&
        typeof item.number === "number"
      ) {
        total += item.number;
      }
    }
    return total;
  }

  return 0;
}
